def _sanitize(geojson_geom: dict) -> dict:
    """
    Drops degenerate polygon rings (fewer than 4 points, e.g. tiny islets
    that collapsed to a single point during upstream simplification) that
    would otherwise fail shapely's LinearRing validity check. These are a
    negligible fraction of the district's total area.
    """
    valid_polygons = []
    for polygon in geojson_geom["coordinates"]:
        exterior_ring = polygon[0]
        if len(exterior_ring) >= 4:
            valid_polygons.append(polygon)
    return {"type": "MultiPolygon", "coordinates": valid_polygons}


def update() -> None:
    Base.metadata.create_all(bind=engine)
    db = SessionLocal()
    try:
        for district, geojson_geom in DISTRICT_GEOMETRIES.items():
            region = db.query(Region).filter(Region.district == district).first()
            if region is None:
                print(f"No region row for {district} - run seed_regions.py first.")
                continue

            clean_geom = _sanitize(geojson_geom)
            shapely_geom = shape(clean_geom)
            region.geometry = from_shape(shapely_geom, srid=4326)
            print(f"Updated {district} (region id={region.id}) with real district boundary.")

        db.commit()
        print("Done.")
    finally:
        db.close()


if __name__ == "__main__":
    update()